   86: function(resolve_include INCLUDE FROM_DIR OUT_VAR)
   87:     set(CANDIDATE "${FROM_DIR}/${INCLUDE}")
   88:     if(EXISTS "${CANDIDATE}" AND NOT IS_DIRECTORY "${CANDIDATE}")
   89:         get_filename_component(CANDIDATE "${CANDIDATE}" REALPATH)
   90:         set(${OUT_VAR} "${CANDIDATE}" PARENT_SCOPE)
   91:         return()
   92:     endif()
   93:     get_filename_component(BASENAME "${INCLUDE}" NAME)
   94:     foreach(DIR IN LISTS INCLUDE_DIRS)
   95:         foreach(NAME IN ITEMS "${INCLUDE}" "${BASENAME}")
   96:             set(CANDIDATE "${DIR}/${NAME}")
   97:             if(EXISTS "${CANDIDATE}" AND NOT IS_DIRECTORY "${CANDIDATE}")
   98:                 get_filename_component(CANDIDATE "${CANDIDATE}" REALPATH)
   99:                 set(${OUT_VAR} "${CANDIDATE}" PARENT_SCOPE)
  100:                 return()
  101:             endif()
  102:         endforeach()
  103:     endforeach()
  104:     set(${OUT_VAR} "" PARENT_SCOPE)
  105: endfunction()
