  107: function(walk_includes START OUT_VAR)
  108:     set(QUEUE "${START}")
  109:     set(SEEN "")
  110:     while(QUEUE)
  111:         list(POP_FRONT QUEUE CURRENT)
  112:         file(STRINGS "${CURRENT}" LINES REGEX "^[ \t]*#[ \t]*include")
  113:         get_filename_component(CURRENT_DIR "${CURRENT}" DIRECTORY)
  114:         foreach(LINE IN LISTS LINES)
  115:             string(REGEX MATCH "[\"<]([^\">]+)[\">]" _ "${LINE}")
  116:             set(INCLUDE "${CMAKE_MATCH_1}")
  117:             if(NOT INCLUDE)
  118:                 continue()
  119:             endif()
  120:             resolve_include("${INCLUDE}" "${CURRENT_DIR}" RESOLVED)
  121:             if(RESOLVED AND NOT RESOLVED IN_LIST SEEN)
  122:                 list(APPEND SEEN "${RESOLVED}")
  123:                 list(APPEND QUEUE "${RESOLVED}")
  124:             endif()
  125:         endforeach()
  126:     endwhile()
  127:     set(${OUT_VAR} "${SEEN}" PARENT_SCOPE)
  128: endfunction()
