  146: function(forbidden_exists SUFFIX OUT_VAR)
  147:     string(REPLACE "." "\\." SUFFIX_RE "${SUFFIX}")
  148:     set(MATCHES ${TREE_FILES})
  149:     list(FILTER MATCHES INCLUDE REGEX "(^|/)${SUFFIX_RE}$")
  150:     if(MATCHES)
